const size_t kGlyphCount = sizeof(kGlyphs) / sizeof(kGlyphs[0]);

const Glyph* findGlyph(uint32_t codePoint) {
  for (size_t index = 0; index < kGlyphCount; ++index) {
    if (kGlyphs[index].codePoint == codePoint) {
      return &kGlyphs[index];
    }
  }

  return nullptr;
}

